      } catch (err) {
        if (/cancelled/.test(err.message)) throw err;
      }
    }
  }
    if (lib.count('obsidian') < n) throw new Error(`made only ${lib.count('obsidian')}/${n} obsidian: ${log.join('; ')}`);
    return { obsidian: lib.count('obsidian'), log };
  };

