      if (b) await bot.dig(b, true);
    } catch (e) {}
  }
}

// 19 safe waypoints avoiding all fire pits and abyss drops
const WAYPOINTS = [
  { x: 46, y: 65, z: -7 },
  { x: 54, y: 65, z: -7 },
  { x: 63, y: 64, z: -7 },
  { x: 63, y: 65, z: -20 },
  { x: 63, y: 66, z: -35 },
